<?php require_once __DIR__.'/../includes/functions.php';$u=require_login();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();db()->prepare('UPDATE notifications SET is_read=1 WHERE id=? AND user_id=?')->execute([(int)($_POST['id']??0),(int)$u['id']]);flash('success','Notification marked as read.');go('notifications.php');}$q=db()->prepare('SELECT * FROM notifications WHERE user_id=? ORDER BY created_at DESC LIMIT 100');$q->execute([(int)$u['id']]);page_start('Notifications'); ?><div class="card"><div class="card-body"><?php foreach($q as $n): ?><div class="d-flex justify-content-between border-bottom py-3 <?= $n['is_read']?'':'fw-semibold' ?>"><div><a class="text-decoration-none" href="<?= e($n['link']?:'#') ?>"><?= e($n['message']) ?></a><div class="small text-secondary"><?= e($n['created_at']) ?></div></div><?php if(!$n['is_read']): ?><form method="post"><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><input type="hidden" name="id" value="<?= $n['id'] ?>"><button class="btn btn-sm btn-outline-primary">Mark read</button></form><?php endif ?></div><?php endforeach ?><?php if(!$q->rowCount()): ?><div class="empty">You are all caught up.</div><?php endif ?></div></div><?php page_end(); ?>
